try:
    parts = gregorian_date_iso.split("-")
    if len(parts) != 3:
        raise ValueError("Gregorian date must be in YYYY-MM-DD format")
    year, month, day = map(int, parts)
    gregorian = Gregorian(year, month, day)
    hijri = gregorian.to_hijri()
    return {
        "hijri_date_iso": hijri.isoformat(),
        "hijri_year": hijri.year,
        "hijri_month": hijri.month,
        "hijri_day": hijri.day,
        "display_date": hijri.dmyformat()
    }
except Exception as e:
    raise ValueError(f"Invalid Gregorian date: {e}")
